     1	/**
     2	 * Guarda antivazamento do resultado de avaliação.
     3	 *
     4	 * Regra do produto (PRD central §4.4; PRD s1 §2.3): o navegador NUNCA recebe o
     5	 * gabarito/transcrição reservada. Se o modelo ecoar um trecho reservado em qualquer
     6	 * campo visível (feedback, evidência, justificativa, incerteza ou motivo), o
     7	 * resultado é retido como `needs_review`, perde a nota e tem as evidências
     8	 * contaminadas removidas.
     9	 *
    10	 * Falso positivo é limitado por desenho: amostras com menos de 25 caracteres
    11	 * (palavras comuns) não disparam a retenção.
    12	 *
    13	 * Módulo puro: zero I/O.
    14	 */
    15	
    16	import type { EvaluationDimension, EvaluationEvidence, EvaluationResult } from "@/domain";
    17	
    18	export const MIN_LEAK_SAMPLE_LENGTH = 25;
    19	export const LEAK_REVIEW_REASON = "resultado retido para revisão de segurança";
    20	
    21	function normalize(text: string): string {
    22	  return text.replace(/\s+/g, " ").trim().toLowerCase();
    23	}
    24	
    25	function usableSamples(referenceSamples: readonly string[]): string[] {
    26	  return referenceSamples
    27	    .map((sample) => normalize(sample))
    28	    .filter((sample) => sample.length >= MIN_LEAK_SAMPLE_LENGTH);
    29	}
    30	
    31	function visibleTextsOf(result: EvaluationResult): string[] {
    32	  const texts: string[] = [result.feedback, result.uncertainty ?? ""];
    33	  for (const dimension of result.dimensions) texts.push(dimension.rationale ?? "");
    34	  for (const evidence of result.evidence) {
    35	    texts.push(evidence.observation, evidence.quote ?? "");
    36	  }
    37	  if (result.verdict === "abstained") texts.push(result.abstentionReason);
    38	  if (result.verdict === "needs_review") texts.push(result.reviewReason);
    39	  return texts.filter((text) => text.length > 0);
    40	}
    41	
    42	/** `true` quando algum campo visível contém uma amostra reservada. */
    43	export function leaksReference(
    44	  result: EvaluationResult,
    45	  referenceSamples: readonly string[],
    46	): boolean {
    47	  const samples = usableSamples(referenceSamples);
    48	  if (samples.length === 0) return false;
    49	  const visible = visibleTextsOf(result).map(normalize);
    50	  return samples.some((sample) => visible.some((text) => text.includes(sample)));
    51	}
    52	
    53	function cleanEvidence(
    54	  evidence: EvaluationEvidence[],
    55	  samples: readonly string[],
    56	): EvaluationEvidence[] {
    57	  return evidence.filter((item) => {
    58	    const text = normalize(`${item.observation} ${item.quote ?? ""}`);
    59	    return !samples.some((sample) => text.includes(sample));
    60	  });
    61	}
    62	
    63	function cleanDimensions(
    64	  dimensions: EvaluationDimension[],
    65	  samples: readonly string[],
    66	): EvaluationDimension[] {
    67	  return dimensions.map((dimension) => {
    68	    if (!dimension.rationale) return dimension;
    69	    const contaminated = samples.some((sample) =>
    70	      normalize(dimension.rationale ?? "").includes(sample),
    71	    );
    72	    if (!contaminated) return dimension;
    73	    const { rationale: _rationale, ...rest } = dimension;
    74	    return rest;
    75	  });
    76	}
    77	
    78	/**
    79	 * Retém o resultado se houver vazamento. Nunca lança e nunca devolve `score`
    80	 * quando retém. `unmeasured` é preservado (é declaração de limitação, não conteúdo
    81	 * da referência).
    82	 */
    83	export function sanitizeEvaluationResult(
    84	  result: EvaluationResult,
    85	  referenceSamples: readonly string[],
    86	): EvaluationResult {
    87	  const samples = usableSamples(referenceSamples);
    88	  if (samples.length === 0 || !leaksReference(result, samples)) return result;
    89	
    90	  return {
    91	    scale: result.scale,
    92	    verdict: "needs_review",
    93	    score: null,
    94	    confidence: result.confidence,
    95	    dimensions: cleanDimensions(result.dimensions, samples),
    96	    evidence: cleanEvidence(result.evidence, samples),
    97	    feedback: "Resultado retido para revisão de segurança.",
    98	    uncertainty: null,
    99	    unmeasured: result.unmeasured,
   100	    evaluator: result.evaluator,
   101	    scoredAt: result.scoredAt,
   102	    reviewReason: LEAK_REVIEW_REASON,
   103	  };
   104	}
