   209	        protectedSamples: [],
   210	        untrusted: [],
   211	      };
   212	    }
   213	
   214	    case "sst": {
   215	      const transcript = clean(question.data.transcript);
   216	      const sample = clean(question.data.sample);
   217	      const keywords = question.data.keywords.map(clean).filter(Boolean);
   218	      return {
   219	        hasReference: transcript.length > 0,
   220	        judgeReference: [transcript, sample, ...keywords].filter(Boolean),
   221	        protectedSamples: [transcript, sample].filter(Boolean),
   222	        untrusted: [],
   223	      };
   224	    }
   225	
   226	    case "lst_mcq_multi":
   227	    case "lst_mcq_single":
   228	    case "lst_hcs":
   229	    case "lst_smw": {
   230	      const transcript = clean(question.data.transcript);
   231	      const options = question.data.options.map(clean).filter(Boolean);
   232	      const questionText = "question" in question.data ? clean(question.data.question) : "";
   233	      const indexes = Array.isArray(question.data.answer)
   234	        ? question.data.answer
   235	        : [question.data.answer];
   236	      const correct = optionTexts(question.data.options, indexes);
   237	      return {
   238	        hasReference: transcript.length > 0,
   239	        judgeReference: [transcript, ...correct].filter(Boolean),
   240	        protectedSamples: [transcript, ...correct].filter(Boolean),
   241	        untrusted: [
   242	          ...(questionText ? [{ label: "PERGUNTA", content: questionText }] : []),
   243	          ...(options.length > 0 ? [{ label: "OPCOES", content: options.join("\n") }] : []),
