   267	      };
   268	    }
   269	
   270	    case "wfd": {
   271	      const sentence = clean(question.data.sentence);
   272	      return {
   273	        hasReference: sentence.length > 0,
   274	        judgeReference: sentence ? [sentence] : [],
   275	        protectedSamples: sentence ? [sentence] : [],
   276	        untrusted: [],
   277	      };
   278	    }
   279	  }
   280	}
   281	
   282	/** Referência e contexto de uma questão, já separados por confiança. */
   283	export function referenceForQuestion(question: Question): QuestionReference {
   284	  return buildFor(question);
   285	}
   286	
   287	/** Monta o bloco "resposta do aluno" no fim do conteúdo não confiável. */
   288	export function withStudentResponse(
   289	  untrusted: readonly UntrustedPart[],
   290	  responseText: string,
   291	): UntrustedPart[] {
   292	  return [...untrusted, { label: "RESPOSTA_DO_ALUNO", content: responseText }];
   293	}

