    19	} from "./evaluation-io";
    20	import { JUDGE_PROMPT_VERSION, composeJudgePrompt } from "./judge-policy";
    21	import { referenceForQuestion, withStudentResponse } from "./reference";
    22	import { abstainedResult, needsReviewResult } from "./result-builders";
    23	
    24	export interface EvaluationRubric {
    25	  text: string;
    26	  version: string;
    27	}
    28	
    29	export interface EvaluationHandlerDependencies {
    30	  adapter: EvaluationAdapter;
    31	  loadQuestionsByType: (type: TaskType) => Promise<Question[]>;
    32	  /** Rubricas chegam de s2; até lá o juiz opera só com a política + referência. */
    33	  rubricFor?: (type: TaskType) => EvaluationRubric | undefined;
    34	  model?: string;
    35	  nowMs?: () => number;
    36	}
    37	
    38	export type EvaluationHandler = (payload: EvaluationRequestPayload) => Promise<EvaluationResponse>;
    39	
    40	export function createEvaluationHandler(deps: EvaluationHandlerDependencies): EvaluationHandler {
    41	  const nowMs = deps.nowMs ?? (() => Date.now());
    42	
    43	  return async function handler(payload) {
    44	    const rubric = deps.rubricFor?.(payload.type);
    45	    const identity = {
    46	      model: deps.model?.trim() || DEFAULT_EVALUATION_MODEL,
    47	      promptVersion: JUDGE_PROMPT_VERSION,
    48	      rubricVersion: rubric?.version.trim() || RUBRIC_UNAVAILABLE_VERSION,
    49	    };
    50	
    51	    let question: Question | undefined;
    52	    try {
    53	      const questions = await deps.loadQuestionsByType(payload.type);
    54	      question = questions.find((candidate) => candidate.id === payload.questionId);
    55	    } catch {
    56	      return {
    57	        evaluation: needsReviewResult(
    58	          identity,
    59	          nowMs(),
    60	          "não foi possível carregar a questão no servidor",
    61	          "O banco de questões não pôde ser carregado; tente novamente.",
    62	        ),
    63	      };
    64	    }
    65	
    66	    if (!question) {
    67	      return {
    68	        evaluation: abstainedResult(
    69	          identity,
    70	          nowMs(),
    71	          "questão não encontrada para o tipo informado",
    72	          "A questão não foi encontrada; a avaliação não foi realizada.",
    73	        ),
    74	      };
    75	    }
    76	    if (question.type !== payload.type) {
    77	      return {
    78	        evaluation: abstainedResult(
    79	          identity,
    80	          nowMs(),
    81	          "questão não corresponde ao tipo informado",
    82	          "A questão não corresponde ao tipo de tarefa; a avaliação não foi realizada.",
    83	        ),
    84	      };
    85	    }
    86	
    87	    const reference = referenceForQuestion(question);
    88	    if (!reference.hasReference) {
    89	      return {
    90	        evaluation: abstainedResult(
    91	          identity,
    92	          nowMs(),
    93	          "referência de avaliação indisponível para esta questão",
    94	          "Esta questão não tem referência suficiente para ser avaliada.",
    95	        ),
    96	      };
    97	    }
    98	
    99	    const systemPrompt = composeJudgePrompt({
   100	      ...(rubric?.text ? { rubric: rubric.text } : {}),
   101	      referenceSamples: reference.judgeReference,
   102	    });
   103	    const untrusted = withStudentResponse(reference.untrusted, responseTextOf(payload.response));
   104	
   105	    const evaluation = await deps.adapter.evaluate({
   106	      ...payload,
   107	      systemPrompt,
   108	      untrusted,
   109	      rubricVersion: identity.rubricVersion,
   110	      promptVersion: identity.promptVersion,
   111	      referenceSamples: reference.protectedSamples,
   112	      model: identity.model,
   113	    });
