     7	 *
     8	 * Entrada inválida vira abstenção com `score: null` — nunca um erro cru de
     9	 * validação e nunca uma nota substituta.
    10	 */
    11	
    12	import { createServerFn } from "@tanstack/react-start";
    13	
    14	import {
    15	  DEFAULT_EVALUATION_MODEL,
    16	  INVALID_INPUT_REASON,
    17	  RUBRIC_UNAVAILABLE_VERSION,
    18	  parseEvaluationRequest,
    19	  type EvaluationRequestPayload,
    20	  type EvaluationResponse,
    21	} from "./evaluation-io";
    22	import { JUDGE_PROMPT_VERSION } from "./judge-policy";
    23	import { abstainedResult } from "./result-builders";
    24	
    25	function invalidInputResult(): EvaluationResponse {
    26	  return {
    27	    evaluation: abstainedResult(
    28	      {
    29	        model: DEFAULT_EVALUATION_MODEL,
    30	        promptVersion: JUDGE_PROMPT_VERSION,
    31	        rubricVersion: RUBRIC_UNAVAILABLE_VERSION,
    32	      },
    33	      Date.now(),
    34	      INVALID_INPUT_REASON,
    35	      "A resposta não pôde ser avaliada porque a entrada é inválida ou expirou.",
    36	    ),
    37	  };
    38	}
    39	
    40	type ValidatedInput = { valid: true; data: EvaluationRequestPayload } | { valid: false };
    41	
    42	export const evaluateResponseFunction = createServerFn({ method: "POST" })
    43	  .inputValidator((raw: unknown): ValidatedInput => {
    44	    const parsed = parseEvaluationRequest(raw);
    45	    return parsed.ok ? { valid: true, data: parsed.data } : { valid: false };
    46	  })
    47	  .handler(async ({ data }): Promise<EvaluationResponse> => {
    48	    if (!data.valid) return invalidInputResult();
    49	    const { evaluateResponse } = await import("./evaluate.server");
    50	    return evaluateResponse(data.data);
    51	  });
