     1	/**
     2	 * Construtores puros de resultados sem nota.
     3	 *
     4	 * Centralizam a regra "falha nunca vira zero": abstenção e revisão sempre têm
     5	 * `score: null`, motivo em pt-BR e identidade de avaliação preenchida.
     6	 */
     7	
     8	import { ATTEMPT_SCORE_SCALE, type Confidence, type EvaluationResult } from "@/domain";
     9	
    10	export interface EvaluationIdentity {
    11	  model: string;
    12	  promptVersion: string;
    13	  rubricVersion: string;
    14	}
    15	
    16	interface ResultBase {
    17	  scale: typeof ATTEMPT_SCORE_SCALE;
    18	  confidence: Confidence;
    19	  dimensions: EvaluationResult["dimensions"];
    20	  evidence: EvaluationResult["evidence"];
    21	  feedback: string;
    22	  uncertainty: string | null;
    23	  unmeasured: string[];
