     1	/**
     2	 * Contrato de entrada/saída da avaliação por IA — seguro para importar no cliente.
     3	 *
     4	 * O cliente envia APENAS `{ type, questionId, response, mode }`. A referência
     5	 * (gabarito/transcrição) é resolvida no servidor e nunca cruza a fronteira.
     6	 *
     7	 * Os limites do §1.12 do PRD (1–20 000 caracteres por campo, id de 1–64 chars,
     8	 * modos practice/session/mock) vivem aqui para serem compartilhados entre o
     9	 * `inputValidator` da server function e o adaptador.
    10	 */
    11	
    12	import { ZodError, z } from "zod";
    13	
    14	import type { EvaluationResult } from "@/domain";
    15	import { isTaskType, type TaskType } from "@/domain";
    16	
    17	export const EVALUATION_MODES = ["practice", "session", "mock"] as const;
    18	export type EvaluationMode = (typeof EVALUATION_MODES)[number];
    19	
    20	export const DEFAULT_EVALUATION_MODEL = "openai/gpt-6-astra";
    21	
    22	export const MAX_QUESTION_ID_LENGTH = 64;
    23	export const MAX_RESPONSE_FIELD_LENGTH = 20_000;
    24	export const QUESTION_ID_PATTERN = /^[A-Za-z0-9._:-]+$/;
    25	
    26	export interface EvaluationResponsePayload {
    27	  text?: string | undefined;
    28	  transcript?: string | undefined;
    29	}
    30	
    31	export interface EvaluationRequestPayload {
    32	  type: TaskType;
    33	  questionId: string;
    34	  response: EvaluationResponsePayload;
    35	  mode: EvaluationMode;
    36	}
    37	
    38	/** DTO devolvido pela server function — só o contrato de domínio. */
    39	export interface EvaluationResponse {
    40	  evaluation: EvaluationResult;
    41	}
    42	
    43	const responseField = z.string().max(MAX_RESPONSE_FIELD_LENGTH).optional();
    44	
    45	export const evaluationRequestSchema = z
    46	  .object({
    47	    type: z.string().refine((value): value is TaskType => isTaskType(value), {
    48	      message: "tipo de tarefa desconhecido",
    49	    }),
    50	    questionId: z
    51	      .string()
    52	      .min(1)
    53	      .max(MAX_QUESTION_ID_LENGTH)
    54	      .regex(QUESTION_ID_PATTERN, "questionId inválido"),
    55	    response: z
    56	      .object({
    57	        text: responseField,
    58	        transcript: responseField,
    59	      })
    60	      .strict(),
    61	    mode: z.enum(EVALUATION_MODES),
    62	  })
    63	  .strict();
    64	
    65	export type EvaluationRequestParseResult =
    66	  { ok: true; data: EvaluationRequestPayload } | { ok: false; error: ZodError };
    67	
    68	export function parseEvaluationRequest(raw: unknown): EvaluationRequestParseResult {
    69	  const parsed = evaluationRequestSchema.safeParse(raw);
    70	  if (parsed.success) return { ok: true, data: parsed.data };
    71	  return { ok: false, error: parsed.error };
    72	}
    73	
    74	/** Texto agregado da resposta do aluno (só campos preenchidos). */
    75	export function responseTextOf(response: EvaluationResponsePayload): string {
    76	  return [response.text, response.transcript]
    77	    .filter((value): value is string => typeof value === "string" && value.length > 0)
    78	    .join("\n\n");
    79	}
