   120	      type: item.type,
   121	      questionId: item.questionId,
   122	      referenceScore: item.referenceScore,
   123	      verdict,
   124	      score,
   125	    };
   126	  };
   127	
   128	  try {
   129	    const questions = await deps.loadQuestionsByType(item.type);
   130	    const question = questions.find((candidate) => candidate.id === item.questionId);
   131	    if (!question) return finish("abstained", null, "question_not_found");
   132	    if (question.type !== item.type) return finish("abstained", null, "type_mismatch");
   133	
   134	    const reference = referenceForQuestion(question);
   135	    if (!reference.hasReference) return finish("abstained", null, "reference_unavailable");
   136	
   137	    const rubric = deps.rubricFor(item.type);
   138	    const rubricVersion = rubric.version.trim() || RUBRIC_UNAVAILABLE_VERSION;
   139	
   140	    const result = await deps.adapter.evaluate({
   141	      type: item.type,
   142	      questionId: item.questionId,
   143	      response: item.response,
   144	      mode: "practice",
   145	      systemPrompt: composeJudgePrompt({
   146	        ...(rubric.text.trim() ? { rubric: rubric.text } : {}),
   147	        referenceSamples: reference.judgeReference,
   148	      }),
   149	      untrusted: withStudentResponse(reference.untrusted, responseTextOf(item.response)),
   150	      rubricVersion,
   151	      promptVersion: JUDGE_PROMPT_VERSION,
   152	      referenceSamples: reference.protectedSamples,
   153	      model: deps.model,
   154	    });
