    12	import type { TaskType, Verdict } from "@/domain";
    13	
    14	export const CALIBRATION_LEVELS = ["high", "medium", "low", "insufficient"] as const;
    15	export type CalibrationLevel = (typeof CALIBRATION_LEVELS)[number];
