    12	/** Nunca mais do que os 22 tipos do formato vigente. */
    13	export const MAX_CALIBRATION_TYPES = TASK_TYPES.length;
    14	
    15	const taskTypeSchema = z.custom<TaskType>(
    16	  (value) => typeof value === "string" && (TASK_TYPES as readonly string[]).includes(value),
    17	  { message: "tipo de tarefa inválido" },
    18	);
    19	
    20	export const calibrationRequestSchema = z
    21	  .object({
    22	    types: z
    23	      .array(taskTypeSchema)
    24	      .transform((types) => Array.from(new Set(types)))
    25	      .refine((types) => types.length <= MAX_CALIBRATION_TYPES, {
    26	        message: `no máximo ${String(MAX_CALIBRATION_TYPES)} tipos por execução`,
    27	      })
    28	      .optional(),
    29	  })
    30	  .strict();
