/* Auditoria s5 — sonda das guardas puras. Não escreve nada no repositório. */
import { sanitizeEvaluationResult, leaksReference } from "/dev-server/src/lib/ai/leak-guard";
import { buildEvaluatorMessages, wrapUntrusted } from "/dev-server/src/lib/ai/prompt-injection";
import { composeJudgePrompt } from "/dev-server/src/lib/ai/judge-policy";
import { referenceForQuestion } from "/dev-server/src/lib/ai/reference";

type Dim = { id: string; label: string; status: "measured" | "proxy" | "not_measured"; score: number | null; rationale?: string };
type Ev = { observation: string; dimensionId?: string; quote?: string };

const SCALE = "attempt_0_100" as never;

function result(over: {
  feedback?: string;
  uncertainty?: string;
  dims?: Dim[];
  evidence?: Ev[];
  unmeasured?: string[];
}): never {
  return {
    scale: SCALE,
    verdict: "scored",
    score: 80,
    confidence: "medium",
    dimensions: over.dims ?? [
      { id: "content", label: "Conteúdo", status: "measured", score: 80, rationale: "ok" },
    ],
    evidence: over.evidence ?? [{ observation: "fala clara", dimensionId: "content" }],
    feedback: over.feedback ?? "Bom trabalho.",
    uncertainty: over.uncertainty ?? null,
    unmeasured: over.unmeasured ?? [],
    evaluator: { model: "m", promptVersion: "p", rubricVersion: "r" },
    scoredAt: new Date(0).toISOString(),
  } as never;
}

// ---------- gabaritos REAIS do banco ----------
const wfd = require("/dev-server/src/data/bank/questions/wfd.json");
const mcq = require("/dev-server/src/data/bank/questions/read_mcq_multi.json");
const wfdItems = (Array.isArray(wfd) ? wfd : wfd.questions);
const mcqItems = (Array.isArray(mcq) ? mcq : mcq.questions);

const S1: string = wfdItems[0].data.sentence;
const mcqItem = mcqItems[0];
const S2: string = mcqItem.data.options[mcqItem.data.answer[0]];
const refWfd = referenceForQuestion(wfdItems[0]);
const refMcq = referenceForQuestion(mcqItem);

console.log("S1 (wfd):", JSON.stringify(S1), "len", S1.length);
console.log("S2 (mcq):", JSON.stringify(S2), "len", S2.length);
console.log("protectedSamples wfd:", refWfd.protectedSamples.map((s: string) => s.length));
console.log("protectedSamples mcq:", refMcq.protectedSamples.map((s: string) => s.length));

function check(name: string, res: never, samples: readonly string[]) {
  const out = sanitizeEvaluationResult(res, samples) as { verdict: string; score: number | null };
  const raw = leaksReference(res, samples);
  console.log(
    `[${raw ? "RETIDO" : "PASSOU"}] ${name} → verdict=${out.verdict} score=${String(out.score)}`,
  );
}

console.log("\n--- A. vazamento literal no feedback (>=25 chars) ---");
check("feedback = S1 completo", result({ feedback: `Você deveria ter escrito: ${S1}` }), [S1]);
check("feedback = 30 chars de S2", result({ feedback: `A opção correta era ${S2.slice(0, 30)}` }), [S2]);
check("quote = S1", result({ evidence: [{ observation: "trecho", quote: S1 }] }), [S1]);

console.log("\n--- B. caixa/espaços ---");
check(
  "S1 em MAIÚSCULAS com espaços duplicados",
  result({ feedback: `  ${S1.toUpperCase().replaceAll(" ", "   ")}  ` }),
  [S1],
);

console.log("\n--- C. trecho curto (<25) — falso positivo esperado NÃO disparar ---");
check("S2 primeiros 24 chars", result({ feedback: `${S2.slice(0, 24)}` }), [S2]);

console.log("\n--- D. vazamento dividido entre campos ---");
const half = Math.floor(S1.length / 2);
check(
  "metade em feedback + metade em uncertainty",
  result({ feedback: S1.slice(0, half), uncertainty: S1.slice(half) }),
  [S1],
);

console.log("\n--- E. canais NÃO vigiados pelo leak-guard ---");
check(
  "S1 dentro de dimensions[].label",
  result({
    dims: [{ id: "content", label: S1, status: "measured", score: 80, rationale: "ok" }],
  }),
  [S1],
);
check("S1 dentro de unmeasured[]", result({ unmeasured: [S1] }), [S1]);

