    20	    const nextRunId = value?.trim() || undefined;
    21	    if (!runId && nextRunId) {
    22	      runId = nextRunId;
    23	    }
    24	    if (!runIdResolved) {
    25	      runIdResolved = true;
    26	      resolveRunId(runId);
    27	    }
    28	  };
    29	  if (runId) publishRunId(runId);
    30	
    31	  return {
    32	    fetch: async (input: RequestInfo | URL, init?: RequestInit) => {
    33	      const headers = new Headers(init?.headers);
    34	      if (runId && !headers.has(LOVABLE_AIG_RUN_ID_HEADER)) {
    35	        headers.set(LOVABLE_AIG_RUN_ID_HEADER, runId);
    36	      }
    37	
    38	      try {
    39	        const response = await fetch(input, { ...init, headers });
    40	        publishRunId(response.headers.get(LOVABLE_AIG_RUN_ID_HEADER) ?? undefined);
    41	        return response;
    42	      } catch (error) {
    43	        publishRunId(undefined);
