    56	export function getLovableAiGatewayResponseHeaders(
    57	  providerHeaders: HeadersInit | undefined,
    58	  init?: HeadersInit,
    59	) {
    60	  const headers = new Headers(init);
    61	  const exposedHeaders = new Set(
    62	    (headers.get("Access-Control-Expose-Headers") ?? "")
    63	      .split(",")
    64	      .map((header) => header.trim())
    65	      .filter(Boolean),
    66	  );
    67	
    68	  new Headers(providerHeaders).forEach((value, name) => {
    69	    if (name.toLowerCase().startsWith("x-lovable-aig-")) {
    70	      headers.set(name, value);
    71	      exposedHeaders.add(name);
    72	    }
    73	  });
    74	
    75	  headers.forEach((_, name) => {
    76	    if (name.toLowerCase().startsWith("x-lovable-aig-")) {
    77	      exposedHeaders.add(name);
    78	    }
    79	  });
    80	
    81	  if (exposedHeaders.size > 0) {
    82	    headers.set("Access-Control-Expose-Headers", Array.from(exposedHeaders).join(", "));
    83	  }
    84	
    85	  return headers;
    86	}
