    88	export async function withLovableAiGatewayRunIdHeader(
    89	  response: Response,
    90	  gateway: {
    91	    getRunId: () => string | undefined;
    92	    waitForRunId: () => Promise<string | undefined>;
    93	  },
    94	  init?: HeadersInit,
    95	  options: { waitForUpstreamHeaders?: boolean } = {},
    96	) {
    97	  if (!response.body) {
    98	    const runId = gateway.getRunId();
    99	    const headers = getLovableAiGatewayResponseHeaders(undefined, response.headers);
   100	    new Headers(init).forEach((value, name) => headers.set(name, value));
   101	    if (runId) headers.set(LOVABLE_AIG_RUN_ID_HEADER, runId);
   102	    return new Response(response.body, {
   103	      status: response.status,
   104	      statusText: response.statusText,
   105	      headers: getLovableAiGatewayResponseHeaders(undefined, headers),
   106	    });
   107	  }
   108	
   109	  const reader = response.body.getReader();
   110	  const firstChunk = reader.read();
   111	  const runId =
   112	    options.waitForUpstreamHeaders === false ? gateway.getRunId() : await gateway.waitForRunId();
   113	  const headers = getLovableAiGatewayResponseHeaders(undefined, response.headers);
   114	  new Headers(init).forEach((value, name) => headers.set(name, value));
   115	  if (runId) headers.set(LOVABLE_AIG_RUN_ID_HEADER, runId);
   116	
   117	  const body = new ReadableStream({
   118	    async start(controller) {
   119	      try {
   120	        const first = await firstChunk;
   121	        if (first.done) {
   122	          controller.close();
   123	          return;
   124	        }
   125	        controller.enqueue(first.value);
   126	        while (true) {
   127	          const chunk = await reader.read();
   128	          if (chunk.done) break;
   129	          controller.enqueue(chunk.value);
   130	        }
   131	        controller.close();
   132	      } catch (error) {
   133	        controller.error(error);
   134	      }
   135	    },
   136	    cancel(reason?: unknown) {
   137	      return reader.cancel(reason);
   138	    },
   139	  });
   140	
   141	  return new Response(body, {
   142	    status: response.status,
   143	    statusText: response.statusText,
   144	    headers: getLovableAiGatewayResponseHeaders(undefined, headers),
   145	  });
