/**
 * Reprodução determinística do bloqueio, SEM chamada de IA.
 * O provider aponta para 127.0.0.1:1 (porta fechada): se houver rede, falha imediata.
 * A chave é falsa e só existe neste processo.
 */
process.env["LOVABLE_API_KEY"] = "chave-falsa-de-auditoria-sem-valor";

const { createGatewayEvaluationCall } = await import(
  "/dev-server/src/lib/ai/gateway/evaluate-call.server.ts"
);

const call = createGatewayEvaluationCall({ baseURL: "http://127.0.0.1:1/v1" });

try {
  const result = await call({
    systemPrompt: "Você é um avaliador de treino.",
    untrusted: [{ label: "RESPOSTA_DO_ALUNO", content: "hello world" }],
    promptVersion: "judge-policy@1",
    rubricVersion: "rubric@1",
    model: "openai/gpt-6-astra",
  });
  console.log("RETORNOU (inesperado):", JSON.stringify(result).slice(0, 200));
} catch (error) {
  console.log("name:", error?.name);
  console.log("constructor:", error?.constructor?.name);
  console.log("message:", String(error?.message).slice(0, 300));
  console.log("cause:", String(error?.cause?.message ?? "").slice(0, 300));
}

