    String(prot.length).padEnd(8),
    String(usable.length).padEnd(4),
    String(shortest).padEnd(5),
    armed ? "sim" : "NÃO",
  );
  if (armed) {
    // prova de que a guarda reage com a amostra real deste tipo
    const sample = usable[0];
    const fake = {
