      dimensions: [{ id: "x", label: "x", status: "measured", score: 90 }],
      evidence: [{ observation: "ok" }],
      feedback: `A resposta correta é: ${sample}`,
      uncertainty: null,
      unmeasured: [],
      evaluator: { model: "m", promptVersion: "p", rubricVersion: "r" },
      scoredAt: new Date().toISOString(),
    };
    const caught = leaksReference(fake, prot);
    const partial = sample.slice(0, Math.max(25, Math.floor(sample.length * 0.4)));
    const fake2 = { ...fake, feedback: `Trecho: ${partial}` };
    const caughtPartial = leaksReference(fake2, prot);
    console.log(
      "   ↳ eco literal detectado:",
      caught,
      "| eco de",
      partial.length,
      "de",
      sample.length,
      "chars detectado:",
      caughtPartial,
    );
  }
}
console.log("\ntipos com guarda DESARMADA:", disarmed);

